"use client"

// From chatcn, chat, voice and agent UI for shadcn: https://chatcn.dev

import * as React from "react"
import { forwardRef, createElement, type SVGAttributes, type ForwardRefExoticComponent, type RefAttributes } from "react"
import { cn } from "@/lib/utils"

/** chatcn theme variables and utilities this file uses, light and dark. */
const CHATCN_CSS = ":root{--chatcn-accent:var(--chatcn-gray-1000);--chatcn-amber:oklch(0.555 0.125 60);--chatcn-amber-bg:oklch(0.975 0.028 85);--chatcn-amber-border:oklch(0.890 0.075 80);--chatcn-blue:oklch(0.550 0.180 258);--chatcn-blue-bg:oklch(0.970 0.016 250);--chatcn-blue-border:oklch(0.880 0.055 255);--chatcn-card:oklch(1 0 0);--chatcn-diff-add-fg:oklch(0.500 0.130 150);--chatcn-diff-del-fg:oklch(0.540 0.200 27);--chatcn-ease-standard:ease;--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill:var(--chatcn-gray-100);--chatcn-fill-active:var(--chatcn-gray-300);--chatcn-fill-hover:var(--chatcn-gray-200);--chatcn-gray-100:oklch(0.970 0 0);--chatcn-gray-1000:oklch(0.145 0 0);--chatcn-gray-200:oklch(0.950 0 0);--chatcn-gray-300:oklch(0.930 0 0);--chatcn-gray-700:oklch(0.700 0 0);--chatcn-gray-800:oklch(0.525 0 0);--chatcn-gray-900:oklch(0.440 0 0);--chatcn-green-bg:oklch(0.970 0.024 155);--chatcn-green-border:oklch(0.880 0.065 155);--chatcn-radius-lg:12px;--chatcn-radius-sm:6px;--chatcn-radius-xs:4px;--chatcn-red-bg:oklch(0.970 0.016 20);--chatcn-red-border:oklch(0.890 0.055 20);--chatcn-shadow-sm:0 0 0 1px oklch(0 0 0 / 0.06), 0 1px 2px -1px oklch(0 0 0 / 0.06), 0 2px 4px oklch(0 0 0 / 0.04)}.dark{--chatcn-accent:var(--chatcn-gray-1000);--chatcn-amber:oklch(0.800 0.140 74);--chatcn-amber-bg:oklch(0.780 0.150 74 / 0.12);--chatcn-amber-border:oklch(0.780 0.150 74 / 0.32);--chatcn-blue:oklch(0.710 0.140 252);--chatcn-blue-bg:oklch(0.690 0.150 252 / 0.14);--chatcn-blue-border:oklch(0.690 0.150 252 / 0.36);--chatcn-card:oklch(0.175 0 0);--chatcn-diff-add-fg:oklch(0.780 0.150 152);--chatcn-diff-del-fg:oklch(0.740 0.160 22);--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill:var(--chatcn-gray-100);--chatcn-fill-active:var(--chatcn-gray-300);--chatcn-fill-hover:var(--chatcn-gray-200);--chatcn-gray-100:oklch(0.195 0 0);--chatcn-gray-1000:oklch(0.970 0 0);--chatcn-gray-200:oklch(0.225 0 0);--chatcn-gray-300:oklch(0.255 0 0);--chatcn-gray-700:oklch(0.500 0 0);--chatcn-gray-800:oklch(0.620 0 0);--chatcn-gray-900:oklch(0.720 0 0);--chatcn-green-bg:oklch(0.740 0.160 152 / 0.12);--chatcn-green-border:oklch(0.740 0.160 152 / 0.32);--chatcn-red-bg:oklch(0.660 0.190 22 / 0.13);--chatcn-red-border:oklch(0.660 0.190 22 / 0.34);--chatcn-shadow-sm:0 0 0 1px oklch(1 0 0 / 0.08), inset 0 1px 0 oklch(1 0 0 / 0.03), 0 2px 4px oklch(0 0 0 / 0.4)}"
if (typeof document !== "undefined" && !document.getElementById("chatcn-changed-files")) {
  const style = document.createElement("style")
  style.id = "chatcn-changed-files"
  style.textContent = CHATCN_CSS
  document.head.appendChild(style)
}

export type DiffFileStatus = "added" | "modified" | "deleted" | "renamed"

/* -------------------------------------------------------------------------------------------------
 * Parts
 * -----------------------------------------------------------------------------------------------*/

const STATUS_NAME: Record<DiffFileStatus, string> = {
  added: "Added",
  modified: "Modified",
  deleted: "Deleted",
  renamed: "Renamed",
}

const STATUS_LETTER: Record<DiffFileStatus, string> = {
  added: "A",
  modified: "M",
  deleted: "D",
  renamed: "R",
}

/** A, M, D or R in a tinted badge. The letter is the signal; the hue (green, amber, red, blue) backs it up. */
export function FileStatusBadge({ status, className }: { status: DiffFileStatus; className?: string }) {
  return (
    <span
      data-slot="file-status"
      data-file-status={status}
      title={STATUS_NAME[status]}
      className={cn(
        "rounded-(--chatcn-radius-xs) text-[0.75rem]/[1rem] grid size-4 shrink-0 place-items-center font-mono leading-none font-medium",
        // The familiar code review colors: added green, modified amber, deleted red, renamed blue.
        status === "added"
          ? "bg-(color:--chatcn-green-bg) text-(color:--chatcn-diff-add-fg) shadow-[inset_0_0_0_1px_var(--chatcn-green-border)]"
          : status === "deleted"
            ? "bg-(color:--chatcn-red-bg) text-(color:--chatcn-diff-del-fg) shadow-[inset_0_0_0_1px_var(--chatcn-red-border)]"
            : status === "renamed"
              ? "bg-(color:--chatcn-blue-bg) text-(color:--chatcn-blue) shadow-[inset_0_0_0_1px_var(--chatcn-blue-border)]"
              : "bg-(color:--chatcn-amber-bg) text-(color:--chatcn-amber) shadow-[inset_0_0_0_1px_var(--chatcn-amber-border)]",
        className,
      )}
    >
      <span aria-hidden="true">{STATUS_LETTER[status]}</span>
      <span className="sr-only">{STATUS_NAME[status]}</span>
    </span>
  )
}

/**
 * Splits a file name for middle truncation: the head may shrink to an ellipsis, the tail (the end
 * of the stem plus the extension) always stays, so "navigation-provider.tsx" reads "navig…ider.tsx".
 */
function splitName(name: string, keep = 8) {
  if (name.length <= keep + 4) return { head: name, tail: "" }
  return { head: name.slice(0, -keep), tail: name.slice(-keep) }
}

/** A file name that truncates in the middle, so the extension and the end of the stem stay. */
export function FileName({ name }: { name: string }) {
  const { head, tail } = splitName(name)
  return (
    <>
      <span className="min-w-0 truncate">{head}</span>
      {tail ? <span className="shrink-0">{tail}</span> : null}
    </>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

/** What the list needs from a file. A `DiffFile` from chatcn-diff fits as is. */
export interface ChangedFile {
  path: string
  oldPath?: string
  status: DiffFileStatus
  additions: number
  deletions: number
}

export interface ChangedFilesProps extends Omit<React.ComponentProps<"div">, "title" | "defaultValue"> {
  files: ChangedFile[]
  /** Selected path. Controlled. */
  value?: string | null
  defaultValue?: string | null
  onValueChange?: (path: string) => void
  /** Header title. Defaults to "Review changes". Pass `null` to hide the header. */
  title?: React.ReactNode
  /** Controls at the end of the header, for example Accept all. */
  actions?: React.ReactNode
  /** Paths the user has finished reviewing. They show a check and step back. */
  reviewed?: ReadonlyArray<string>
  /** Skeleton rows while the change set loads. */
  loading?: boolean
  /** `plain` sits inside your surface; `card` draws its own. */
  variant?: "plain" | "card"
}

type DiffLineKind = "context" | "add" | "remove"

/** A piece of a changed line. `changed` pieces are the words that differ from the paired line. */
export interface DiffSegment {
  text: string
  changed: boolean
}

export interface DiffLine {
  kind: DiffLineKind
  text: string
  /** Line number in the old file. Set on context and removed lines. */
  oldNumber?: number
  /** Line number in the new file. Set on context and added lines. */
  newNumber?: number
  /** Word-level highlights, only on removed and added lines that pair up and look alike. */
  segments?: DiffSegment[]
}

export interface DiffHunk {
  /** Stable id from the hunk position, for example `h-40-42`. */
  id: string
  oldStart: number
  oldLines: number
  newStart: number
  newLines: number
  /** The text after the second `@@`, usually the enclosing function. */
  heading?: string
  lines: DiffLine[]
  additions: number
  deletions: number
  /** False while a streamed hunk is still arriving. */
  complete: boolean
}

interface DiffSource {
  old: string[]
  new: string[]
  /** Whether the old text ended with a newline, kept by `applyHunks`. */
  oldEol: boolean
  newEol: boolean
}

export interface DiffFile {
  path: string
  /** Previous path, set on renames. */
  oldPath?: string
  status: DiffFileStatus
  hunks: DiffHunk[]
  additions: number
  deletions: number
  binary?: boolean
  /** Both full versions, when known. Lets a viewer expand collapsed unchanged lines. */
  source?: DiffSource
  /** False while a streamed patch is still writing this file. */
  complete: boolean
}

/** Totals across files, for a review header. */
function diffStats(files: ReadonlyArray<Pick<DiffFile, "additions" | "deletions">>) {
  let additions = 0
  let deletions = 0
  for (const file of files) {
    additions += file.additions
    deletions += file.deletions
  }
  return { files: files.length, additions, deletions }
}

function Counts({
  additions,
  deletions,
  selected,
}: {
  additions: number
  deletions: number
  selected?: boolean
}) {
  // On the selected row's darker fill the subtle gray drops under 4.5:1, so it steps up to muted.
  const dim = selected ? "text-(color:--chatcn-fg-muted)" : "text-(color:--chatcn-fg-subtle)"
  return (
    <span className="text-[0.75rem]/[1rem] inline-flex shrink-0 gap-1.5 font-mono tabular-nums">
      <span
        aria-hidden="true"
        className={additions > 0 ? "text-(color:--chatcn-diff-add-fg) font-medium" : dim}
      >
        +{additions.toLocaleString("en-US")}
      </span>
      <span aria-hidden="true" className={deletions > 0 ? "text-(color:--chatcn-diff-del-fg)" : dim}>
        -{deletions.toLocaleString("en-US")}
      </span>
      <span className="sr-only">
        {additions} added, {deletions} removed
      </span>
    </span>
  )
}

/** `src/app/page.tsx` to `{ dir: "src/app/", name: "page.tsx" }`. */
function splitPath(path: string) {
  const slash = path.lastIndexOf("/")
  return slash === -1
    ? { dir: "", name: path }
    : { dir: path.slice(0, slash + 1), name: path.slice(slash + 1) }
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

const iconNode: IconNode = [
  ["path", {"d":"m4.5 12.75 3.23 3.23a2.5 2.5 0 0 0 3.54 0l8.48-8.48"}],
]

const CheckIcon: Icon = /* @__PURE__ */ createIcon("check", iconNode)

/**
 * Five cells that show the share of added to removed lines, the way GitHub does: green for added,
 * red for removed, a faint cell for unused when the change is under five lines.
 */
export function ChangeBar({ additions, deletions }: { additions: number; deletions: number }) {
  const total = additions + deletions
  const cells = 5
  const used = Math.min(cells, total)
  let added = total === 0 ? 0 : Math.round((additions / total) * used)
  // A file with any additions keeps at least one ink cell, and the same for deletions.
  if (additions > 0 && added === 0) added = 1
  if (deletions > 0 && added === used && used > 1) added = used - 1
  const removed = used - added
  return (
    <span
      data-slot="change-bar"
      aria-hidden="true"
      // In a narrow list the path needs the room more than the bar does; the counts stay.
      className="flex shrink-0 gap-px @max-[19rem]/files:hidden"
    >
      {Array.from({ length: cells }, (_, i) => (
        <span
          key={i}
          className={cn(
            "size-2 rounded-[2px]",
            i < added
              ? "bg-(color:--chatcn-diff-add-fg)"
              : i < added + removed
                ? "bg-(color:--chatcn-diff-del-fg)"
                : "bg-(color:--chatcn-fill-active)",
          )}
        />
      ))}
    </span>
  )
}

/* -------------------------------------------------------------------------------------------------
 * ChangedFiles
 * -----------------------------------------------------------------------------------------------*/

/**
 * The files an agent changed: status letter, path with the directory dimmed, +/- counts and a
 * five-cell bar. Selecting a file is how you open its diff. A listbox with arrow keys,
 * Home and End; selection follows focus like tabs.
 */
export function ChangedFiles({
  files,
  value: valueProp,
  defaultValue,
  onValueChange,
  title = "Review changes",
  actions,
  reviewed,
  loading = false,
  variant = "plain",
  className,
  ...props
}: ChangedFilesProps) {
  const [valueState, setValueState] = React.useState<string | null>(
    defaultValue === undefined ? (files[0]?.path ?? null) : defaultValue,
  )
  const value = valueProp === undefined ? valueState : valueProp
  const select = (path: string) => {
    if (valueProp === undefined) setValueState(path)
    onValueChange?.(path)
  }

  const totals = diffStats(files)
  const done = new Set(reviewed)
  const optionEls = React.useRef<Array<HTMLDivElement | null>>([])
  const selectedIndex = Math.max(
    0,
    files.findIndex((f) => f.path === value),
  )

  const onKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.metaKey || event.ctrlKey || event.altKey) return
    const current = optionEls.current.indexOf(event.target as HTMLDivElement)
    if (current === -1) return
    let next = current
    if (event.key === "ArrowDown" || event.key === "j") next = current + 1
    else if (event.key === "ArrowUp" || event.key === "k") next = current - 1
    else if (event.key === "Home") next = 0
    else if (event.key === "End") next = files.length - 1
    else if (event.key === "Enter" || event.key === " ") {
      const file = files[current]
      if (file) select(file.path)
      event.preventDefault()
      return
    } else return
    event.preventDefault()
    next = Math.min(Math.max(next, 0), files.length - 1)
    const file = files[next]
    if (!file) return
    select(file.path)
    optionEls.current[next]?.focus()
  }

  const fileWord = files.length === 1 ? "file" : "files"

  return (
    <div
      data-slot="changed-files"
      data-variant={variant}
      className={cn(
        "text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) @container/files flex min-w-0 flex-col",
        variant === "card" && "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm)",
        className,
      )}
      {...props}
    >
      {title !== null ? (
        <div
          data-slot="changed-files-header"
          className={cn(
            "flex min-h-11 items-center gap-2 py-1.5 ps-3.5",
            // Buttons in `actions` carry their own inset; plain counts line up with the rows' 14 px.
            actions ? "pe-2" : "pe-3.5",
          )}
        >
          <div className="flex min-w-0 flex-1 items-baseline gap-2">
            <h3 className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] truncate font-medium">{title}</h3>
            {loading || files.length === 0 ? null : (
              <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
                {files.length} {fileWord}
              </span>
            )}
          </div>
          {loading || files.length === 0 ? null : (
            <Counts additions={totals.additions} deletions={totals.deletions} />
          )}
          {actions}
        </div>
      ) : null}

      {loading ? (
        <div
          role="status"
          aria-busy="true"
          aria-label="Loading changed files"
          className="flex flex-col gap-px p-1.5 pt-0"
        >
          {[64, 48, 72, 40].map((w) => (
            <div key={w} className="flex h-8 items-center gap-2.5 px-2">
              <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) size-4" />
              <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) h-2.5" style={{ width: `${w}%` }} />
            </div>
          ))}
        </div>
      ) : files.length === 0 ? (
        <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) px-3.5 pb-4 text-pretty">
          No files changed yet. Edits appear here as they land.
        </p>
      ) : (
        <div
          role="listbox"
          aria-label="Changed files"
          onKeyDown={onKeyDown}
          className="flex flex-col gap-px p-1.5 pt-0"
        >
          {files.map((file, index) => {
            const selected = file.path === value
            const isDone = done.has(file.path)
            const { dir, name } = splitPath(file.path)
            return (
              // biome-ignore lint/a11y/useKeyWithClickEvents: keys are handled on the listbox (roving focus)
              <div
                key={file.path}
                ref={(el) => {
                  optionEls.current[index] = el
                }}
                role="option"
                aria-selected={selected}
                tabIndex={index === selectedIndex ? 0 : -1}
                onClick={() => select(file.path)}
                data-slot="changed-file"
                data-reviewed={isDone || undefined}
                title={file.oldPath ? `${file.oldPath} to ${file.path}` : file.path}
                className={cn(
                  "rounded-(--chatcn-radius-sm) group/file flex h-8 cursor-default items-center gap-2.5 px-2 outline-none select-none pointer-coarse:h-11",
                  "ease-(--chatcn-ease-standard) transition-colors duration-150",
                  "focus-visible:outline-(color:--chatcn-accent) focus-visible:outline-2 focus-visible:-outline-offset-2",
                  selected ? "bg-(color:--chatcn-fill-active)" : "hover:bg-(color:--chatcn-fill-hover)",
                )}
              >
                <FileStatusBadge status={file.status} />
                <span
                  dir="ltr"
                  className={cn(
                    // Inline-size containment: a long path never sets the list's minimum width.
                    "flex min-w-0 flex-1 font-mono [contain:inline-size]",
                    file.status === "deleted" &&
                      (selected ? "text-(color:--chatcn-fg)" : "text-(color:--chatcn-fg-subtle)"),
                  )}
                >
                  {/* The directory gives way first. The name only truncates when it alone does
                      not fit, in the middle so the extension stays, and always leaves 2ch for the
                      directory's ellipsis. */}
                  {dir ? (
                    // The folder gives way from its start, so the nearest folder stays readable
                    // ("…/runs/load-more.tsx"). The inner run is isolated, so slashes keep their order.
                    <span
                      className={cn(
                        "min-w-0 truncate [direction:rtl]",
                        selected ? "text-(color:--chatcn-fg)" : "text-(color:--chatcn-fg-subtle)",
                      )}
                    >
                      <span className="[direction:ltr] [unicode-bidi:isolate]">{dir}</span>
                    </span>
                  ) : null}
                  <span
                    className={cn(
                      "flex max-w-[calc(100%-2ch)] min-w-0 shrink-0",
                      isDone
                        ? "text-(color:--chatcn-fg-muted)"
                        : file.status === "deleted"
                          ? selected
                            ? "text-(color:--chatcn-fg)"
                            : "text-(color:--chatcn-fg-subtle)"
                          : "text-(color:--chatcn-fg)",
                      selected && "font-medium",
                    )}
                  >
                    <FileName name={name} />
                  </span>
                </span>
                <Counts additions={file.additions} deletions={file.deletions} selected={selected} />
                {isDone ? (
                  <span className="text-(color:--chatcn-fg-muted) flex w-[2.75rem] shrink-0 justify-end @max-[19rem]/files:w-auto [&_svg]:size-3.5">
                    <CheckIcon aria-hidden="true" />
                    <span className="sr-only">Reviewed</span>
                  </span>
                ) : (
                  <ChangeBar additions={file.additions} deletions={file.deletions} />
                )}
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

export default ChangedFiles

